<div class="container-fluid" id="rops-payment" data-store="{{ route('naxas.restaurantops.pos.payments.store',$order) }}" data-version="{{ $order->version }}"><div class="row justify-content-center"><div class="col-xl-8"><div class="card"><div class="card-header d-flex justify-content-between"><strong>Order #{{ $order->getKey() }} · {{ str($order->service_type)->replace('_',' ') }}</strong><strong>{{ $order->outstanding_total }} BDT</strong></div><div class="card-body"><div id="payment-errors" class="alert alert-danger d-none"></div><div class="row g-2 mb-3"><div class="col"><button class="btn btn-outline-success w-100 tender-add" data-method="cash">Cash</button></div><div class="col"><button class="btn btn-outline-primary w-100 tender-add" data-method="card">Card</button></div><div class="col"><button class="btn btn-outline-info w-100 tender-add" data-method="mobile">Mobile</button></div></div><div id="tenders"></div><div class="d-flex justify-content-between fs-5 my-3"><span>Remaining</span><strong id="remaining">{{ $order->outstanding_total }}</strong></div><button id="confirm-payment" class="btn btn-lg btn-primary w-100" disabled>Confirm payment</button><div id="success" class="alert alert-success d-none mt-3">Official payment synchronized. <a id="receipt-link">Print receipt</a></div></div></div></div></div></div>
<template id="tender-template"><div class="tender-row border rounded p-2 mb-2 row g-2"><div class="col-md-2"><strong class="method-label"></strong><input type="hidden" class="method"></div><div class="col-md-3"><input class="form-control amount" inputmode="decimal" placeholder="Amount / cash received"></div><div class="col-md-2 provider-wrap d-none"><select class="form-select provider"><option value="">Provider</option>@foreach($providers as $code=>$label)<option value="{{ $code }}">{{ $label }}</option>@endforeach</select></div><div class="col"><input class="form-control reference" placeholder="Transaction reference"></div><div class="col-auto"><button class="btn btn-outline-danger remove" type="button">Remove</button></div><div class="col-12 small change"></div></div></template>
<script>(()=>{const root=document.querySelector('#rops-payment'),box=document.querySelector('#tenders'),total=Number({{ json_encode($order->outstanding_total) }}),confirm=document.querySelector('#confirm-payment');let busy=false;const idempotencyKey=crypto.randomUUID();const refresh=()=>{let applied=0;[...box.children].forEach((row,i,a)=>{const amount=Number(row.querySelector('.amount').value)||0,method=row.querySelector('.method').value,remain=Math.max(0,total-applied),use=Math.min(amount,remain);applied+=use;row.querySelector('.change').textContent=method==='cash'&&i===a.length-1&&amount>remain?'Change preview: '+(amount-remain).toFixed(4):''});document.querySelector('#remaining').textContent=Math.max(0,total-applied).toFixed(4);confirm.disabled=busy||box.children.length===0||Math.abs(total-applied)>.00001};document.querySelectorAll('.tender-add').forEach(b=>b.onclick=()=>{const row=document.querySelector('#tender-template').content.firstElementChild.cloneNode(true),m=b.dataset.method;row.querySelector('.method').value=m;row.querySelector('.method-label').textContent=m.toUpperCase();row.querySelector('.reference').classList.toggle('d-none',m==='cash');row.querySelector('.provider-wrap').classList.toggle('d-none',m!=='mobile');row.querySelector('.remove').onclick=()=>{row.remove();refresh()};row.querySelector('.amount').oninput=refresh;box.append(row);refresh()});confirm.onclick=async()=>{if(busy)return;busy=true;refresh();const errors=document.querySelector('#payment-errors');errors.classList.add('d-none');const tenders=[...box.children].map(r=>({method:r.querySelector('.method').value,amount:r.querySelector('.amount').value,provider:r.querySelector('.provider').value,reference:r.querySelector('.reference').value}));try{const response=await fetch(root.dataset.store,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||'','Idempotency-Key':idempotencyKey},body:JSON.stringify({version:Number(root.dataset.version),tenders})}),json=await response.json();if(!response.ok)throw new Error(json.error?.message||Object.values(json.errors||{}).flat().join(' '));document.querySelector('#success').classList.remove('d-none');document.querySelector('#receipt-link').href=json.data.receipt?location.pathname.replace(/\/payment$/,'/receipt'):'#';confirm.textContent='Paid';}catch(e){busy=false;errors.textContent=e.message;errors.classList.remove('d-none');refresh()}}})();</script>
